// Cycle 7.1: exact qnorm(0.975) for 95% CIs (was 1.96; ~1.3e-5 drift vs metafor).
var Z975 = 1.959963984540054;

function parse(text) {
  // Preserve quoted treatment/study labels and optional study identifiers.
  const records = []; let row = [], field = "", quoted = false;
  for (let i = 0; i <= text.length; i++) {
    const c = i === text.length ? "\n" : text[i];
    if (c === '"') {
      if (quoted && text[i + 1] === '"') { field += '"'; i++; }
      else quoted = !quoted;
    } else if (!quoted && (c === ',' || c === '\n')) {
      row.push(field.trim()); field = "";
      if (c === '\n') { records.push(row); row = []; }
    } else if (c !== '\r' || quoted) field += c;
  }
  if (quoted) return [];
  return records.map((parts, i) => {
    const te = Number(parts[2]), se = Number(parts[3]);
    if (!parts[0] || !parts[1] || parts[0] === parts[1] ||
        !parts[2] || !Number.isFinite(te) || !Number.isFinite(se) || se <= 0) return null;
    return { A: parts[0], B: parts[1], te, se, study: parts[4] || `row_${i + 1}` };
  }).filter(Boolean);
}
function escapeMarkup(value) {
  return String(value).replace(/&/g, "&amp;").replace(/</g, "&lt;")
    .replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}
function refuse(reason) {
  _lastInco = { status: "refused", reason };
  document.getElementById("ns-body").innerHTML = "";
  document.getElementById("ns-plot").innerHTML = "";
  document.getElementById("dbt").textContent = reason;
}
function inputIssue(rows) {
  if (rows.length < 3) return "At least 3 valid contrasts are required.";
  const studies = new Map();
  for (const r of rows) {
    if (!studies.has(r.study)) studies.set(r.study, []);
    studies.get(r.study).push(r);
  }
  for (const group of studies.values()) {
    if (new Set(group.flatMap(r => [r.A, r.B])).size > 2)
      return "Multi-arm studies are unsupported: correlated contrasts require study covariance.";
  }
  if ([...studies.values()].some(group => group.length > 1))
    return "Repeated study IDs are unsupported: enter one independent contrast per study.";
  const all = new Set(rows.flatMap(r => [r.A, r.B]));
  const seen = new Set([rows[0].A]);
  for (let old = -1; old !== seen.size;) {
    old = seen.size;
    for (const r of rows) if (seen.has(r.A) || seen.has(r.B)) { seen.add(r.A); seen.add(r.B); }
  }
  if (seen.size !== all.size) return "The treatment network is disconnected.";
  return null;
}

// --- math utils (shared) ---
function zeros(n, m) { return Array.from({ length: n }, () => Array(m).fill(0)); }
function transpose(A) { return A[0].map((_, j) => A.map(r => r[j])); }
function matMul(A, B) { const n = A.length, m = B[0].length, k = B.length; const C = zeros(n, m);
  for (let i = 0; i < n; i++) for (let j = 0; j < m; j++) for (let p = 0; p < k; p++) C[i][j] += A[i][p] * B[p][j]; return C; }
function matVec(A, v) { return A.map(r => r.reduce((s, x, j) => s + x * v[j], 0)); }
function invert(M) {
  const n = M.length;
  const A = M.map((r, i) => [...r, ...Array.from({ length: n }, (_, j) => i === j ? 1 : 0)]);
  for (let i = 0; i < n; i++) {
    let piv = A[i][i];
    if (Math.abs(piv) < 1e-14) {
      for (let k = i + 1; k < n; k++) if (Math.abs(A[k][i]) > 1e-14) { [A[i], A[k]] = [A[k], A[i]]; piv = A[i][i]; break; }
    }
    if (Math.abs(piv) < 1e-14) throw new Error("singular");
    for (let j = 0; j < 2 * n; j++) A[i][j] /= piv;
    for (let k = 0; k < n; k++) if (k !== i) {
      const f = A[k][i]; for (let j = 0; j < 2 * n; j++) A[k][j] -= f * A[i][j];
    }
  }
  return A.map(r => r.slice(n));
}

function pnorm(x) {
  const t = 1 / (1 + 0.3275911 * Math.abs(x) / Math.SQRT2);
  const y = 1 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * Math.exp(-x * x / 2);
  return x >= 0 ? 0.5 * (1 + y) : 0.5 * (1 - y);
}
function pz(z) { return 1 - chiSqCDF(z * z, 1); }

// Inverse-variance pool of a set of rows. tau2 ≥ 0 enables RE weights;
// default (omitted) is FE (τ²=0).
function ivPool(rows, tau2) {
  const t2 = (typeof tau2 === "number" && Number.isFinite(tau2) && tau2 > 0) ? tau2 : 0;
  const w = rows.map(r => 1 / (r.se * r.se + t2));
  const sw = w.reduce((a, b) => a + b, 0);
  const mean = rows.reduce((acc, r, i) => acc + w[i] * r.te, 0) / sw;
  return { mean, se: Math.sqrt(1 / sw), k: rows.length };
}
// Backward-compat alias for any existing test that references fePool.
function fePool(rows) { return ivPool(rows, 0); }

function fitNMA(rows, refTrt, tau2) {
  // V9-06 RE option: callers may pass tau2 ≥ 0 to inflate weights to
  // w_i = 1/(SE² + τ²). Defaults to tau2=0 (FE) for backward compat.
  const t2 = (typeof tau2 === "number" && Number.isFinite(tau2) && tau2 > 0) ? tau2 : 0;
  const trtSet = new Set();
  rows.forEach(r => { trtSet.add(r.A); trtSet.add(r.B); });
  let trts = [...trtSet].sort();
  if (!refTrt || !trts.includes(refTrt)) refTrt = trts[0];
  trts = [refTrt, ...trts.filter(t => t !== refTrt)];
  const idx = Object.fromEntries(trts.map((t, i) => [t, i]));
  const nBasic = trts.length - 1;
  const X = zeros(rows.length, nBasic);
  const y = rows.map(r => r.te);
  const w = rows.map(r => 1 / (r.se * r.se + t2));
  rows.forEach((r, i) => { const iA = idx[r.A], iB = idx[r.B]; if (iA > 0) X[i][iA - 1] = 1; if (iB > 0) X[i][iB - 1] = -1; });
  const Xt = transpose(X);
  const XtW = Xt.map(rx => rx.map((x, j) => x * w[j]));
  const XtWX = matMul(XtW, X);
  const XtWy = matVec(XtW, y);
  const cov = invert(XtWX);
  const beta = matVec(cov, XtWy);
  const fit = y.map((yi, i) => X[i].reduce((s, x, j) => s + x * beta[j], 0));
  const dev = y.map((yi, i) => w[i] * (yi - fit[i]) ** 2);
  const Q = dev.reduce((a, b) => a + b, 0);
  const df = Math.max(0, rows.length - nBasic);
  return { trts, idx, X, y, w, beta, cov, Q, df, dev, nBasic, refTrt, tau2: t2 };
}

// V9-06: τ² estimators using the consistency-model residuals. Caller
// re-fits fitNMA with the estimated τ² to get RE-weighted estimates.
function tau2_DL(rows) {
  const fit0 = fitNMA(rows, null, 0);
  if (fit0.df <= 0) return 0;
  // Generalized DerSimonian-Laird / Jackson moment denominator for a
  // multi-parameter WLS network model (DerSimonian & Kacker 2007;
  // Jackson, White & Riley 2013; netmeta method.tau="DL"):
  //   C = tr(W) − tr( (XᵀWX)⁻¹ XᵀW²X )
  // The earlier `ΣW − ΣW²/ΣW` form is only the intercept-only
  // (single-parameter) special case; it diverges by ~16 % once
  // nBasic > 1 (multi-treatment network) and failed netmeta DL parity.
  // For a 2-treatment network (nBasic=1) this reduces exactly to the
  // old form, so 2-arm behaviour is unchanged.
  const X = fit0.X, w = fit0.w, cov = fit0.cov, p = fit0.nBasic, n = fit0.X.length;
  const XtW2X = zeros(p, p);
  for (let i = 0; i < n; i++) {
    const wi2 = w[i] * w[i];
    for (let a = 0; a < p; a++) {
      const xa = X[i][a]; if (xa === 0) continue;
      for (let b = 0; b < p; b++) XtW2X[a][b] += xa * wi2 * X[i][b];
    }
  }
  let trCW2 = 0;
  for (let a = 0; a < p; a++) for (let b = 0; b < p; b++) trCW2 += cov[a][b] * XtW2X[b][a];
  const sumW = w.reduce((s, x) => s + x, 0);
  const denom = sumW - trCW2;
  if (denom <= 1e-12) return 0;
  return Math.max(0, (fit0.Q - fit0.df) / denom);
}
function tau2_PM(rows) {
  // Iterative Paule-Mandel: find τ² s.t. weighted Q(τ²) = df. Bracket via
  // monotone bisection (Q is monotone-decreasing in τ²).
  const fit0 = fitNMA(rows, null, 0);
  if (fit0.df <= 0) return 0;
  const Qat = (t2) => fitNMA(rows, null, t2).Q;
  if (Qat(0) <= fit0.df) return 0;
  let lo = 0, hi = Math.max(0.001, fit0.Q / fit0.df);
  // expand until Q(hi) ≤ df
  for (let g = 0; g < 50 && Qat(hi) > fit0.df; g++) hi *= 2;
  for (let i = 0; i < 100; i++) {
    const mid = 0.5 * (lo + hi);
    if (Qat(mid) > fit0.df) lo = mid; else hi = mid;
    if (hi - lo < 1e-13 * Math.max(1, mid)) break;
  }
  return 0.5 * (lo + hi);
}
function estimateTau2(rows, method) {
  if (method === "DL") return tau2_DL(rows);
  if (method === "PM") return tau2_PM(rows);
  return 0;  // FE
}

function fmt(x, d = 3) { return Number.isFinite(x) ? x.toFixed(d) : "—"; }

function nodeSplit(rows, refTrt, tau2) {
  const pairs = new Set();
  for (const r of rows) { pairs.add(JSON.stringify([r.A, r.B].sort())); }
  const results = [];
  for (const key of pairs) {
    const [a, b] = JSON.parse(key);
    const direct = rows.filter(r => (r.A === a && r.B === b) || (r.A === b && r.B === a)).map(r => ({
      ...r,
      te: r.A === a ? r.te : -r.te,
      A: a, B: b,
    }));
    const others = rows.filter(r => !((r.A === a && r.B === b) || (r.A === b && r.B === a)));
    if (direct.length === 0 || others.length === 0) continue;
    // Check graph connectivity before solving: floating-point elimination
    // can invert a disconnected Laplacian with a tiny nonzero pivot.
    const reachable = new Set([a]);
    for (let old = -1; old !== reachable.size;) {
      old = reachable.size;
      for (const r of others) if (reachable.has(r.A) || reachable.has(r.B)) {
        reachable.add(r.A); reachable.add(r.B);
      }
    }
    if (!reachable.has(b)) continue;
    let ind = null;
    try {
      const fit = fitNMA(others, a, tau2);
      const iB = fit.idx[b];
      if (iB == null || iB < 1) continue;
      // fitNMA β is the (b vs ref-a) contrast; `direct` is normalised to
      // the (a vs b) orientation, so the indirect estimate must be
      // negated to compare like-for-like (else diff/z/p and the plot
      // whiskers are mis-oriented). Matches netmeta::netsplit.
      const est = fit.beta[iB - 1];
      const se = Math.sqrt(fit.cov[iB - 1][iB - 1]);
      ind = { mean: -est, se };
    } catch (e) { continue; }
    const dirPool = ivPool(direct, tau2);
    if (!ind) continue;
    const diff = dirPool.mean - ind.mean;
    const seDiff = Math.sqrt(dirPool.se * dirPool.se + ind.se * ind.se);
    const z = diff / seDiff;
    const p = pz(z);
    results.push({
      comparison: `${a} vs ${b}`,
      direct: dirPool,
      indirect: ind,
      diff, seDiff, z, p,
      kDirect: direct.length, kIndirect: others.length,
    });
  }
  return results;
}

function dbt(rows, tau2) {
  // Design-by-treatment inconsistency test (Higgins 2012): compare the consistency model
  // (basic-parameter contrasts only) against a full-design model that gives each design
  // its own contrast parameter. Q_cons − Q_full ~ χ² on df_cons − df_full.
  // V9-06: tau2 ≥ 0 uses RE-inflated weights w_i = 1/(SE² + τ²) for both models.
  const t2 = (typeof tau2 === "number" && Number.isFinite(tau2) && tau2 > 0) ? tau2 : 0;
  try {
    const cons = fitNMA(rows, null, t2);
    const tagged = rows.map(r => ({ ...r, __design: JSON.stringify([r.A, r.B].sort()) }));
    const designs = [...new Set(tagged.map(r => r.__design))];
    if (designs.length <= cons.nBasic) {
      return { Q: 0, df: 0, p: NaN, note: "No closed loops: inconsistency is not testable." };
    }
    const n = tagged.length;
    const nCols = designs.length;
    const X = Array.from({ length: n }, () => Array(nCols).fill(0));
    tagged.forEach((r, i) => { X[i][designs.indexOf(r.__design)] = 1; });
    tagged.forEach((r, i) => {
      const [a, b] = [r.A, r.B].sort();
      if (r.A !== a) X[i][designs.indexOf(r.__design)] = -1;
    });
    const y = tagged.map(r => r.te);
    const w = tagged.map(r => 1 / (r.se * r.se + t2));
    const Xt = X[0].map((_, j) => X.map(row => row[j]));
    const XtW = Xt.map(rx => rx.map((x, j) => x * w[j]));
    // XtWX
    const k = Xt.length;
    const XtWX = Array.from({ length: k }, () => Array(k).fill(0));
    for (let i = 0; i < k; i++) for (let j = 0; j < k; j++) for (let p = 0; p < n; p++) XtWX[i][j] += XtW[i][p] * X[p][j];
    let inv;
    try { inv = invert(XtWX); } catch (_) { return { Q: cons.Q, df: cons.df, p: NaN, note: "inconsistency model singular" }; }
    if (!inv) return { Q: cons.Q, df: cons.df, p: NaN, note: "inconsistency model singular" };
    const XtWy = XtW.map(row => row.reduce((s, v, p) => s + v * y[p], 0));
    const beta = inv.map(row => row.reduce((s, v, i) => s + v * XtWy[i], 0));
    const fit_ = y.map((yi, i) => X[i].reduce((s, x, j) => s + x * beta[j], 0));
    const Qfull = y.reduce((s, yi, i) => s + w[i] * (yi - fit_[i]) ** 2, 0);
    const dfFull = Math.max(0, n - nCols);
    // Nested weighted projections: avoid cancellation of large residual sums.
    const dQ = y.reduce((sum, _, i) => sum + w[i] * (fit_[i] - cons.X[i].reduce((v, x, j) => v + x * cons.beta[j], 0)) ** 2, 0);
    const dDf = Math.max(0, cons.df - dfFull);
    const p = dDf > 0 ? 1 - chiSqCDF(dQ, dDf) : NaN;
    return { Q: dQ, df: dDf, p };
  } catch (e) { return { Q: NaN, df: NaN, p: NaN }; }
}

// (invert defined above in math utils; reusing it.)

// Accurate chi-square CDF = regularised lower incomplete gamma
// P(k/2, x/2) (Numerical Recipes gammp; ~1e-14). Replaces the prior
// Wilson-Hilferty approximation, which was notably inaccurate at low df
// (e.g. the df=1 design-by-treatment test) vs R's exact pchisq.
function _lngamma(z) {
  const g = 7, c = [0.99999999999980993, 676.5203681218851,
    -1259.1392167224028, 771.32342877765313, -176.61502916214059,
    12.507343278686905, -0.13857109526572012, 9.9843695780195716e-6,
    1.5056327351493116e-7];
  if (z < 0.5) return Math.log(Math.PI / Math.sin(Math.PI * z)) - _lngamma(1 - z);
  z -= 1; let x = c[0];
  for (let i = 1; i < g + 2; i++) x += c[i] / (z + i);
  const t = z + g + 0.5;
  return 0.5 * Math.log(2 * Math.PI) + (z + 0.5) * Math.log(t) - t + Math.log(x);
}
function _gammp(s, x) {
  if (x <= 0) return 0;
  if (x < s + 1) {
    let ap = s, sum = 1 / s, del = sum;
    for (let n = 0; n < 300; n++) {
      ap += 1; del *= x / ap; sum += del;
      if (Math.abs(del) < Math.abs(sum) * 1e-15) break;
    }
    return sum * Math.exp(-x + s * Math.log(x) - _lngamma(s));
  }
  let b = x + 1 - s, c = 1e300, d = 1 / b, h = d;
  for (let i = 1; i < 300; i++) {
    const an = -i * (i - s);
    b += 2; d = an * d + b; if (Math.abs(d) < 1e-300) d = 1e-300;
    c = b + an / c; if (Math.abs(c) < 1e-300) c = 1e-300;
    d = 1 / d; const del = d * c; h *= del;
    if (Math.abs(del - 1) < 1e-15) break;
  }
  return 1 - Math.exp(-x + s * Math.log(x) - _lngamma(s)) * h;
}
function chiSqCDF(x, k) {
  if (k <= 0 || x <= 0) return 0;
  return _gammp(k / 2, x / 2);
}

let _lastInco = null;

function run() {
  const rows = parse(document.getElementById("src").value);
  const issue = inputIssue(rows);
  if (issue) { refuse(issue); return; }
  const modelSel = document.getElementById("f-model");
  const method = modelSel ? modelSel.value : "FE";
  let tau2;
  try { tau2 = estimateTau2(rows, method); fitNMA(rows, undefined, tau2); }
  catch (_) { refuse("Network fit is singular or numerically invalid."); return; }
  const ns = nodeSplit(rows, undefined, tau2);
  const body = document.getElementById("ns-body");
  const __bodyParts = [""];
  for (const r of ns) {
    const flag = r.p < 0.05 ? "incon" : "cons";
    const label = r.p < 0.05 ? "inconsistent" : "consistent";
    __bodyParts.push(`<tr><td><code>${escapeMarkup(r.comparison)}</code></td>
      <td>${fmt(r.direct.mean)} (${fmt(r.direct.se)})</td>
      <td>${fmt(r.indirect.mean)} (${fmt(r.indirect.se)})</td>
      <td>${fmt(r.diff)} (${fmt(r.seDiff)})</td>
      <td>${fmt(r.z, 2)}</td>
      <td>${fmt(r.p, 3)}</td>
      <td><span class="chip ${flag}">${label}</span></td></tr>`);
  }
  const g = dbt(rows, tau2);
  const tauTxt = method === "FE" ? "fixed-effect (τ²=0)" : `${method} τ² = ${fmt(tau2, 4)}`;
  document.getElementById("dbt").innerHTML = `
    <p>Design-by-treatment Q = <code>${fmt(g.Q, 2)}</code>, df = <code>${g.df}</code>, p = <code>${fmt(g.p, 3)}</code>.
    <span class="chip ${g.p < 0.05 ? 'incon' : 'cons'}">${!Number.isFinite(g.p) ? "inconsistency is not testable" : g.p < 0.05 ? "evidence of inconsistency" : "no evidence of inconsistency"}</span></p>
    <p style="font-size:0.83rem;color:var(--muted);margin-top:0.3rem">Model: ${tauTxt}.</p>`;
  drawNS(ns);
  body.innerHTML = __bodyParts.join("");

  // Engine-state exposure for R-parity tests (do-no-harm).
  try {
    const net = fitNMA(rows);
    const estimates = Object.create(null);
    net.trts.forEach((t, i) => {
      estimates[t] = i === 0
        ? { est: 0, se: 0 }
        : { est: net.beta[i - 1], se: Math.sqrt(net.cov[i - 1][i - 1]) };
    });
    // RE-refit network estimates under the selected τ² (== FE when τ²=0),
    // for netmeta(random=TRUE) parity checks.
    const netRE = fitNMA(rows, undefined, tau2);
    const estimatesRandom = Object.create(null);
    netRE.trts.forEach((t, i) => {
      estimatesRandom[t] = i === 0
        ? { est: 0, se: 0 }
        : { est: netRE.beta[i - 1], se: Math.sqrt(netRE.cov[i - 1][i - 1]) };
    });
    _lastInco = {
      trts: net.trts, Q: net.Q, df: net.df, estimates: estimates,
      estimatesRandom: estimatesRandom, Qrandom: netRE.Q,
      model: method, tau2: tau2,
      nodeSplit: ns.map(r => ({
        comparison: r.comparison,
        direct: { mean: r.direct.mean, se: r.direct.se },
        indirect: { mean: r.indirect.mean, se: r.indirect.se },
        diff: r.diff, seDiff: r.seDiff, z: r.z, p: r.p,
      })),
      dbt: { Q: g.Q, df: g.df, p: Number.isFinite(g.p) ? g.p : null },
    };
  } catch (_) { refuse("Network fit is singular or numerically invalid."); }
}

window.__almIncoLoad = function (text) {
  document.getElementById("src").value = text;
  run();
};
window._almLastInco = function () { return _lastInco; };

function drawNS(ns) {
  const svg = document.getElementById("ns-plot");
  const W = 600, H = Math.max(200, 40 + ns.length * 30 + 20);
  svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
  const __svgParts = [""];
  const padL = 120, padR = 30;
  const plotW = W - padL - padR;
  const allLimits = ns.flatMap(r => [r.direct.mean - Z975 * r.direct.se, r.direct.mean + Z975 * r.direct.se, r.indirect.mean - Z975 * r.indirect.se, r.indirect.mean + Z975 * r.indirect.se]);
  const lo = Math.min(0, ...allLimits) - 0.3, hi = Math.max(0, ...allLimits) + 0.3;
  const X = v => padL + (v - lo) / (hi - lo) * plotW;
  __svgParts.push(`<line x1="${X(0)}" y1="${10}" x2="${X(0)}" y2="${10 + ns.length * 30}" stroke="currentColor" stroke-dasharray="3 3" opacity="0.35"/>`);
  ns.forEach((r, i) => {
    const y = 30 + i * 30;
    __svgParts.push(`<text x="${padL - 8}" y="${y + 4}" text-anchor="end" font-size="11" fill="currentColor">${escapeMarkup(r.comparison)}</text>`);
    // direct
    const dLo = r.direct.mean - Z975 * r.direct.se, dHi = r.direct.mean + Z975 * r.direct.se;
    __svgParts.push(`<line x1="${X(dLo)}" y1="${y - 6}" x2="${X(dHi)}" y2="${y - 6}" stroke="var(--accent)" stroke-width="1.3"/>`);
    __svgParts.push(`<rect x="${X(r.direct.mean) - 3.5}" y="${y - 9.5}" width="7" height="7" fill="var(--accent)"/>`);
    // indirect
    const iLo = r.indirect.mean - Z975 * r.indirect.se, iHi = r.indirect.mean + Z975 * r.indirect.se;
    __svgParts.push(`<line x1="${X(iLo)}" y1="${y + 6}" x2="${X(iHi)}" y2="${y + 6}" stroke="var(--warn)" stroke-width="1.3" stroke-dasharray="3 2"/>`);
    __svgParts.push(`<rect x="${X(r.indirect.mean) - 3.5}" y="${y + 2.5}" width="7" height="7" fill="none" stroke="var(--warn)" stroke-width="1.5"/>`);
